// ========================================
// SISTEMA DE AUDIO - LANCER GAME
// ========================================

const sonidos = {
    menu: new Audio("audio/muscia-menu.mp3"),
    pregunta: new Audio("audio/inicio-pregunta.mp3"),
    correcto: new Audio("audio/respuesta-bien.mp3"),
    incorrecto: new Audio("audio/respuesta-mal.mp3")
};

sonidos.menu.loop = true;
sonidos.menu.volume = 0.35;

sonidos.pregunta.volume = 0.65;
sonidos.correcto.volume = 0.75;
sonidos.incorrecto.volume = 0.75;

// Reproducir un efecto de sonido
function reproducirSonido(nombre) {
    const sonido = sonidos[nombre];

    if (!sonido) return;

    sonido.currentTime = 0;

    sonido.play().catch(error => {
        console.log("No se pudo reproducir el sonido:", error);
    });
}

// Iniciar música del menú
function iniciarMusicaMenu() {
    sonidos.menu.play().catch(error => {
        console.log("La música espera una interacción del usuario.");
    });
}

// Detener música del menú
function detenerMusicaMenu() {
    sonidos.menu.pause();
    sonidos.menu.currentTime = 0;
}


const materias = Object.keys(bancoPreguntas);
const valores = [50, 40, 30, 20, 10];
const nombresEquipos = ["Equipo 1", "Equipo 2", "Equipo 3", "Equipo 4", "Equipo 5", "Equipo 6"];

let puntuaciones = [0, 0, 0, 0, 0, 0];
let tableroPartida = {};
let preguntaActiva = null;
let equipoActivo = 0;
let partidaTerminada = false;

const tablero = document.getElementById("tablero");
const equiposContenedor = document.getElementById("equipos");
const modal = document.getElementById("modal");
const modalFinal = document.getElementById("modalFinal");
const preguntaTexto = document.getElementById("preguntaTexto");
const modalMateria = document.getElementById("modalMateria");
const modalValor = document.getElementById("modalValor");
const selectorEquipo = document.getElementById("equipoTurno");
const opcionesContenedor = document.getElementById("opciones");
const resultado = document.getElementById("resultado");
const accionesManual = document.getElementById("accionesManual");

function mezclar(lista) {
    const copia = [...lista];
    for (let i = copia.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [copia[i], copia[j]] = [copia[j], copia[i]];
    }
    return copia;
}

function crearSelectorEquipos() {
    selectorEquipo.innerHTML = "";
    nombresEquipos.forEach((nombre, indice) => {
        const opcion = document.createElement("option");
        opcion.value = indice;
        opcion.textContent = nombre;
        selectorEquipo.appendChild(opcion);
    });
}

function nuevaPartida(confirmar = false) {
    if (confirmar && !window.confirm("¿Quieres iniciar una nueva partida? Se borrarán los puntos y el avance actual.")) return;

    puntuaciones = [0, 0, 0, 0, 0, 0];
    equipoActivo = 0;
    partidaTerminada = false;
    preguntaActiva = null;
    tableroPartida = {};

    materias.forEach(materia => {
        const disponibles = mezclar(bancoPreguntas[materia]);
        tableroPartida[materia] = valores.map((valor, indice) => ({
            valor,
            pregunta: disponibles[indice],
            usada: false
        }));
    });

    modal.classList.remove("visible");
    modal.setAttribute("aria-hidden", "true");
    modalFinal.classList.remove("visible");
    modalFinal.setAttribute("aria-hidden", "true");
    crearTablero();
    crearMarcador();
    actualizarProgreso();
}

function crearTablero() {
    tablero.innerHTML = "";

    const encabezados = ["Materia", ...valores.map(v => `${v} puntos`)];
    encabezados.forEach(texto => {
        const celda = document.createElement("div");
        celda.className = "celda-cabecera";
        celda.textContent = texto;
        tablero.appendChild(celda);
    });

    materias.forEach((materia, indiceMateria) => {
        const celdaMateria = document.createElement("div");
        celdaMateria.className = "celda-materia";
        celdaMateria.innerHTML = `<span class="materia-num">${String(indiceMateria + 1).padStart(2, "0")}</span><span></span>`;
        celdaMateria.querySelector("span:last-child").textContent = materia;
        tablero.appendChild(celdaMateria);

        tableroPartida[materia].forEach((casilla, indiceValor) => {
            const boton = document.createElement("button");
            boton.type = "button";
            boton.className = "celda-pregunta";
            boton.textContent = casilla.valor;
            boton.disabled = casilla.usada || partidaTerminada;
            boton.setAttribute("aria-label", `${materia}, ${casilla.valor} puntos`);
            boton.addEventListener("click", () => abrirPregunta(materia, indiceValor));
            tablero.appendChild(boton);
        });
    });
}

function crearMarcador() {
    equiposContenedor.innerHTML = "";

    nombresEquipos.forEach((nombre, indice) => {
        const tarjeta = document.createElement("article");
        tarjeta.className = "equipo-card" + (indice === equipoActivo ? " activo" : "");
        tarjeta.innerHTML = `
            <div class="equipo-cabecera">
                <span class="equipo-nombre">${nombre}</span>
                <span class="equipo-tag">UNIDAD ${String(indice + 1).padStart(2, "0")}</span>
            </div>
            <div class="equipo-puntos" id="puntos-${indice}">${puntuaciones[indice].toLocaleString("es-MX")}</div>
            <div class="equipo-controles">
                <button type="button" data-equipo="${indice}" data-cambio="10">+10 PTS</button>
                <button type="button" data-equipo="${indice}" data-cambio="-10">−10 PTS</button>
            </div>
        `;
        equiposContenedor.appendChild(tarjeta);
    });

    equiposContenedor.querySelectorAll("button[data-equipo]").forEach(boton => {
        boton.addEventListener("click", () => {
            const equipo = Number(boton.dataset.equipo);
            const cambio = Number(boton.dataset.cambio);
            ajustarPuntos(equipo, cambio);
        });
    });
}

function ajustarPuntos(equipo, cambio) {
    puntuaciones[equipo] = Math.max(0, puntuaciones[equipo] + cambio);
    actualizarMarcador();
}

function actualizarMarcador() {
    puntuaciones.forEach((puntos, indice) => {
        const elemento = document.getElementById(`puntos-${indice}`);
        if (elemento) elemento.textContent = puntos.toLocaleString("es-MX");
    });
}

function actualizarProgreso() {
    let usadas = 0;
    let total = 0;
    materias.forEach(materia => {
        tableroPartida[materia].forEach(casilla => {
            total++;
            if (casilla.usada) usadas++;
        });
    });
    document.getElementById("progresoTexto").textContent = `${usadas} / ${total} preguntas`;
    document.getElementById("progresoBarra").style.width = `${total ? (usadas / total) * 100 : 0}%`;
}

function abrirPregunta(materia, indiceValor) {
    if (partidaTerminada) return;
    const casilla = tableroPartida[materia][indiceValor];
    if (!casilla || casilla.usada || !casilla.pregunta) return;

    preguntaActiva = { materia, indiceValor, valor: casilla.valor, datos: casilla.pregunta, respondida: false };
    modalMateria.textContent = materia;
    modalValor.textContent = `${casilla.valor} PTS`;
    preguntaTexto.textContent = casilla.pregunta.question;
    selectorEquipo.value = String(equipoActivo);
    document.getElementById("volverTablero").textContent = "Volver al tablero";
    selectorEquipo.disabled = false;
    opcionesContenedor.innerHTML = "";
    resultado.textContent = "";
    resultado.className = "resultado";
    accionesManual.hidden = true;

    casilla.pregunta.options.forEach((respuesta, indice) => {
        const boton = document.createElement("button");
        boton.type = "button";
        boton.className = "opcion";
        const letra = document.createElement("span");
        letra.className = "opcion-letra";
        letra.textContent = String.fromCharCode(65 + indice);
        const texto = document.createElement("span");
        texto.textContent = respuesta;
        boton.append(letra, texto);
        boton.addEventListener("click", () => comprobarRespuesta(indice, boton));
        opcionesContenedor.appendChild(boton);
    });

    modal.classList.add("visible");
    modal.setAttribute("aria-hidden", "false");
}

function comprobarRespuesta(seleccion, botonSeleccionado) {
    if (!preguntaActiva || preguntaActiva.respondida) return;
    equipoActivo = Number(selectorEquipo.value);
    document.querySelectorAll(".equipo-card").forEach((tarjeta, indice) => tarjeta.classList.toggle("activo", indice === equipoActivo));
    const correcta = preguntaActiva.datos.correct;
    const botones = [...opcionesContenedor.querySelectorAll(".opcion")];

    if (correcta === null || correcta === undefined) {
        preguntaActiva.seleccion = seleccion;
        preguntaActiva.respondida = true;
        botones.forEach(b => b.disabled = true);
        botonSeleccionado.classList.add("incorrecta");
        selectorEquipo.disabled = true;
        resultado.textContent = "Respuesta registrada. Este documento no marca la respuesta correcta; el moderador debe validar el resultado.";
        resultado.classList.add("aviso");
        accionesManual.hidden = false;
        return;
    }

    preguntaActiva.respondida = true;
    botones.forEach((boton, indice) => {
        boton.disabled = true;
        if (indice === correcta) boton.classList.add("correcta");
    });
    selectorEquipo.disabled = true;

    if (seleccion === correcta) {
        puntuaciones[equipoActivo] += preguntaActiva.valor;
        resultado.textContent = `¡RESPUESTA CORRECTA! ${nombresEquipos[equipoActivo]} obtiene +${preguntaActiva.valor} puntos.`;
        resultado.classList.add("ok");
        botonSeleccionado.classList.add("correcta");
    } else {
        resultado.textContent = `RESPUESTA INCORRECTA. La respuesta correcta era ${String.fromCharCode(65 + correcta)}.`;
        resultado.classList.add("error");
        botonSeleccionado.classList.add("incorrecta");
    }

    tableroPartida[preguntaActiva.materia][preguntaActiva.indiceValor].usada = true;
    actualizarMarcador();
    actualizarProgreso();
}

function cerrarPregunta() {
    if (preguntaActiva && preguntaActiva.respondida) {
        tableroPartida[preguntaActiva.materia][preguntaActiva.indiceValor].usada = true;
        crearTablero();
        actualizarProgreso();
    }
    modal.classList.remove("visible");
    modal.setAttribute("aria-hidden", "true");
    preguntaActiva = null;
    comprobarFinPartida();
}

function resolverManual(otorgarPuntos) {
    if (!preguntaActiva || !preguntaActiva.respondida) return;
    if (otorgarPuntos) {
        puntuaciones[equipoActivo] += preguntaActiva.valor;
        resultado.textContent = `Puntos asignados manualmente: +${preguntaActiva.valor} para ${nombresEquipos[equipoActivo]}.`;
        resultado.className = "resultado ok";
    } else {
        resultado.textContent = "No se otorgaron puntos. La pregunta quedará registrada como contestada.";
        resultado.className = "resultado aviso";
    }
    actualizarMarcador();
    accionesManual.hidden = true;
    document.getElementById("volverTablero").textContent = "Continuar";
}

function comprobarFinPartida() {
    const quedan = materias.some(materia => tableroPartida[materia].some(c => !c.usada));
    if (!quedan) mostrarResultados();
}

function mostrarResultados() {
    partidaTerminada = true;
    crearTablero();
    const ranking = nombresEquipos.map((nombre, indice) => ({ nombre, puntos: puntuaciones[indice] }))
        .sort((a, b) => b.puntos - a.puntos);
    const maximo = ranking[0].puntos;
    const ganadores = ranking.filter(x => x.puntos === maximo).map(x => x.nombre);
    document.getElementById("ganadorTexto").textContent = ganadores.length > 1
        ? `¡Empate entre ${ganadores.join(" y ")} con ${maximo} puntos!`
        : `¡${ganadores[0]} gana la partida con ${maximo} puntos!`;
    const rankingContenedor = document.getElementById("rankingFinal");
    rankingContenedor.innerHTML = "";
    ranking.forEach((equipo, indice) => {
        const fila = document.createElement("div");
        fila.className = "ranking-item";
        const nombre = document.createElement("span");
        nombre.textContent = `${indice + 1}. ${equipo.nombre}`;
        const puntos = document.createElement("strong");
        puntos.textContent = `${equipo.puntos} pts`;
        fila.append(nombre, puntos);
        rankingContenedor.appendChild(fila);
    });
    modalFinal.classList.add("visible");
    modalFinal.setAttribute("aria-hidden", "false");
}

// Eventos de interfaz
crearSelectorEquipos();
selectorEquipo.addEventListener("change", () => {
    equipoActivo = Number(selectorEquipo.value);
    document.querySelectorAll(".equipo-card").forEach((tarjeta, indice) => tarjeta.classList.toggle("activo", indice === equipoActivo));
});
document.getElementById("reiniciar").addEventListener("click", () => nuevaPartida(true));
document.getElementById("cerrarModal").addEventListener("click", cerrarPregunta);
document.getElementById("volverTablero").addEventListener("click", cerrarPregunta);
document.getElementById("manualAcierto").addEventListener("click", () => resolverManual(true));
document.getElementById("manualSinPuntos").addEventListener("click", () => resolverManual(false));
document.getElementById("nuevaPartidaFinal").addEventListener("click", () => nuevaPartida(false));
modal.addEventListener("click", event => { if (event.target === modal) cerrarPregunta(); });
modalFinal.addEventListener("click", event => { if (event.target === modalFinal) { modalFinal.classList.remove("visible"); modalFinal.setAttribute("aria-hidden", "true"); } });
document.addEventListener("keydown", event => {
    if (event.key === "Escape" && modal.classList.contains("visible")) cerrarPregunta();
});

nuevaPartida(false);
